def comps5(g):
    g=np.array(g); H,W=g.shape
    seen=np.zeros_like(g,bool); out=[]
    for r in range(H):
        for c in range(W):
            if g[r,c]==5 and not seen[r,c]:
                q=deque([(r,c)]); seen[r,c]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny,nx]==5 and not seen[ny,nx]:
                            seen[ny,nx]=True; q.append((ny,nx))
                out.append(cells)
    return out
for name,i,o in [("D1",D1i,D1o),("D2",D2i,D2o),("D3",D3i,D3o)]:
    c5=comps5(i)
    print(name,"n5objects:",len(c5),[len(x) for x in c5])
    # check output 5s unchanged
    print("  output same 5s:", all(np.array(i)[r,c]==np.array(o)[r,c] for x in c5 for r,c in x))
    for x in c5:
        ys=[p[0] for p in x]; xs=[p[1] for p in x]
        print("   obj size",len(x),"bbox",(min(ys),min(xs),max(ys),max(xs)))
